```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?airport ?country WHERE {
  VALUES ?airport { dbr:Far_View_Airport dbr:Bellevue_Airfield }

  # get the textual location (either dbo:location or dbp:location)
  OPTIONAL { ?airport dbo:location ?loc . }
  OPTIONAL { ?airport dbp:location ?loc . }
  BIND (COALESCE(?loc, "") AS ?location)

  # derive the country from the location string
  BIND (
    IF(
      REGEX(LCASE(STR(?location)), "ohio|washington|u\\.s\\.|united states"),
      "United States",
      "Unknown"
    )
    AS ?country
  )
}
